.ra-sub { line-height: 1.85; }
.ra-list li { font-size: 16px; }
.ra-why .d, .ra-step .d, .ra-rule .d { font-size: 15px; line-height: 1.7; }
.ra-fix span { font-size: 15px; line-height: 1.7; }
.ra-cmp { font-size: 16px; }
.ra-before4 span, .ra-example { font-size: 14px; }
